import os
from typing import Any, Generator, Optional

def requires_pyvenv_patch(info: dict) -> bool:
    # Check if the platform is macOS
    if info.get('platform') == 'darwin':
        # Check if the macOS version is less than 10.15 (Catalina)
        if float(info.get('release', '0')) < 10.15:
            return True
    return False
